"use client"

import { Avatar as AvatarPrimitive } from "@base-ui/react/avatar"
import type React from "react"
import { cva } from "class-variance-authority"
import { cn } from "@/lib/utils"

import "@/styles/avatar.styles.css"

export type AvatarSize = "xs" | "sm" | "md" | "lg"

const avatarSizeClasses: Record<AvatarSize, string> = {
  xs: "cn-avatar-xs",
  sm: "cn-avatar-sm",
  md: "cn-avatar-md",
  lg: "cn-avatar-lg",
}

export function Avatar({
  className,
  size = "md",
  showBadge = false,
  badgeVariant = "online",
  badgePosition = "top-right",
  children,
  ...props
}: AvatarPrimitive.Root.Props & {
  size?: AvatarSize
  showBadge?: boolean
  badgeVariant?: "online" | "offline" | "busy" | "away"
  badgePosition?: "top-right" | "top-left" | "bottom-right" | "bottom-left"
}): React.ReactElement {
  return (
    <div className="cn-avatar-wrap">
      <AvatarPrimitive.Root
        className={cn("cn-avatar", avatarSizeClasses[size], className)}
        data-size={size}
        data-slot="avatar"
        {...props}
      >
        {children}
      </AvatarPrimitive.Root>
      {showBadge ? <AvatarBadge variant={badgeVariant} badgePosition={badgePosition} /> : null}
    </div>
  )
}

export function AvatarImage({
  className,
  ...props
}: AvatarPrimitive.Image.Props): React.ReactElement {
  return (
    <AvatarPrimitive.Image
      className={cn("size-full object-cover", className)}
      data-slot="avatar-image"
      {...props}
    />
  )
}

export function AvatarFallback({
  className,
  ...props
}: AvatarPrimitive.Fallback.Props): React.ReactElement {
  return (
    <AvatarPrimitive.Fallback
      className={cn(
        "flex size-full items-center justify-center rounded-[inherit] text-current",
        className
      )}
      data-slot="avatar-fallback"
      {...props}
    />
  )
}

const avatarBadgeVariants = cva("cn-avatar-marker", {
  variants: {
    variant: {
      online: "bg-[var(--cn-status-success-text)]", // available
      offline: "bg-muted-foreground", // neutral
      busy: "bg-[var(--cn-status-destructive-text)]", // do not disturb
      away: "bg-[var(--cn-status-warning-text)]", // idle/away
    },
    badgePosition: {
      "top-right": "top-0 right-0",
      "top-left": "top-0 left-0",
      "bottom-right": "bottom-0 end-0",
      "bottom-left": "bottom-0 start-0",
    },
  },
  defaultVariants: {
    variant: "online",
    badgePosition: "top-right",
  },
})

export function AvatarBadge({
  className,
  variant = "online",
  badgePosition = "top-right",
  ...props
}: React.ComponentProps<"span"> & {
  variant?: "online" | "offline" | "busy" | "away"
  badgePosition?: "top-right" | "top-left" | "bottom-right" | "bottom-left"
}): React.ReactElement {
  return (
    <span
      aria-hidden="true"
      className={cn(avatarBadgeVariants({ variant, badgePosition }), className)}
      data-slot="avatar-badge"
      {...props}
    />
  )
}

export function AvatarGroup({
  className,
  ...props
}: React.ComponentProps<"div">): React.ReactElement {
  return <div className={cn("cn-avatar-group", className)} data-slot="avatar-group" {...props} />
}

export function AvatarGroupCount({
  className,
  size = "md",
  ...props
}: React.ComponentProps<"span"> & { size?: AvatarSize }): React.ReactElement {
  return (
    <span
      className={cn(
        "cn-avatar-count",
        "cursor-default hover:z-10 leading-none",
        avatarSizeClasses[size],
        className
      )}
      data-slot="avatar-group-count"
      {...props}
    />
  )
}

export { AvatarPrimitive }

@layer components {
  .cn-avatar,
  .cn-avatar-count {
    --avatar-size: 40;
    --avatar-type: 14;
    --avatar-marker: 8;
    position: relative;
    display: inline-flex;
    width: calc(var(--avatar-size) * var(--cn-unit));
    height: calc(var(--avatar-size) * var(--cn-unit));
    flex-shrink: 0;
    align-items: center;
    justify-content: center;
    overflow: hidden;
    border: 1px solid var(--cn-border);
    border-radius: 9999px;
    background: var(--cn-surface-muted);
    color: var(--cn-text);
    font-size: calc(var(--avatar-type) * var(--cn-unit));
    line-height: 1;
    font-weight: 500;
    vertical-align: middle;
    user-select: none;
  }
  .cn-avatar-xs {
    --avatar-size: 24;
    --avatar-type: 11;
    --avatar-marker: 6;
  }
  .cn-avatar-sm {
    --avatar-size: 32;
    --avatar-type: 12;
    --avatar-marker: 6;
  }
  .cn-avatar-lg {
    --avatar-size: 48;
    --avatar-type: 16;
  }
  .cn-avatar-wrap {
    position: relative;
    display: inline-flex;
  }
  .cn-avatar-marker {
    position: absolute;
    width: calc(8 * var(--cn-unit));
    height: calc(8 * var(--cn-unit));
    border-radius: 9999px;
    outline: 2px solid var(--cn-surface);
  }
  .cn-avatar-wrap:has(.cn-avatar-xs, .cn-avatar-sm) .cn-avatar-marker {
    width: calc(6 * var(--cn-unit));
    height: calc(6 * var(--cn-unit));
  }
  .cn-avatar-group {
    display: flex;
    align-items: center;
  }
  .cn-avatar-group > :not(:first-child) {
    margin-inline-start: calc(-8 * var(--cn-unit));
  }
  .cn-avatar-group :is(.cn-avatar, .cn-avatar-count) {
    outline: 2px solid var(--cn-surface);
  }
}
